const levelOneExamples={"Python syntax":"print(\"Halo, AI Engineer!\")","variables":"nama = \"Salman\"\nlevel = 1\nprint(nama, level)","data types":"nama = \"AI\"\numur = 3\nakurasi = 0.95\naktif = True\nprint(type(nama), type(umur), type(akurasi), type(aktif))","operators":"a = 10\nb = 3\nprint(a + b)\nprint(a % b)\nprint(a >= b)","input/output":"nama = input(\"Nama kamu: \")\nprint(\"Halo,\", nama)","conditionals":"akurasi = 0.92\nif akurasi >= 0.90:\n    print(\"Model memenuhi target\")\nelse:\n    print(\"Model perlu diperbaiki\")","loops":"scores = [0.8, 0.9, 0.95]\nfor score in scores:\n    print(score)","functions":"def tambah(a, b):\n    return a + b\n\nprint(tambah(7, 5))","collections":"fitur = [\"teks\", \"gambar\", \"audio\"]\nprofil = {\"model\": \"demo\", \"aktif\": True}\nprint(fitur[0])\nprint(profil[\"model\"])","comprehensions":"angka = [1, 2, 3, 4]\nkuadrat = [x ** 2 for x in angka]\nprint(kuadrat)","modules":"import math\nprint(math.sqrt(25))","exceptions":"teks = \"123\"\ntry:\n    angka = int(teks)\n    print(angka)\nexcept ValueError:\n    print(\"Input bukan angka bulat\")","debugging":"nilai = 42\nprint(\"DEBUG nilai:\", nilai)\nprint(\"Tipe:\", type(nilai))","problem solving":"data = [3, 7, 2, 9]\ntotal = sum(data)\nrata_rata = total / len(data)\nprint(rata_rata)","CLI projects.":"nama = input(\"Nama proyek: \")\nprint(\"Proyek dibuat:\", nama)"};
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const select=$("#material-level"),search=$("#material-search"),list=$("#material-list");
select.innerHTML=phases.map((p,i)=>'<option value="'+i+'">Level '+(i+1)+' — '+esc(p.title)+'</option>').join("");
const requested=new URLSearchParams(location.search).get("level");if(requested)select.value=String(Math.max(0,Math.min(22,Number(requested)-1)));
const guides=[{"level":1,"goal":"Mampu menulis program Python kecil yang menerima data, memprosesnya, dan menghasilkan output.","prereq":"Tidak perlu pengalaman coding. Siapkan Python atau gunakan tombol Run di halaman ini.","project":"Program CLI penghitung skor sederhana.","flow":"Pelajari sintaks dan tipe data, kendalikan alur, susun fungsi, lalu gabungkan menjadi program kecil."},{"level":2,"goal":"Menulis Python yang modular, mudah diuji, bertipe jelas, dan siap dipelihara.","prereq":"Level 01: variabel, fungsi, collection, exception.","project":"Paket Python kecil dengan validasi input dan unit test.","flow":"Mulai dari objek dan kontrak tipe, lanjut ke iterator/asynchronous, lalu packaging, testing, logging, dan arsitektur."},{"level":3,"goal":"Memahami struktur data, kompleksitas algoritma, sistem operasi, version control, dan jaringan.","prereq":"Python dasar dan fungsi.","project":"Aplikasi CLI yang menyimpan data, memakai Git, dan mengakses endpoint HTTP tiruan.","flow":"Pilih struktur data yang tepat, analisis efisiensi, kelola kode dengan Git/Linux, pahami komunikasi jaringan."},{"level":4,"goal":"Memahami matematika yang menjadi dasar model machine learning.","prereq":"Aritmetika, aljabar dasar, dan Python.","project":"Kalkulator vektor serta simulasi gradient descent satu variabel.","flow":"Bangun intuisi vektor/matriks, turunan/gradien, probabilitas, lalu inferensi statistik."},{"level":5,"goal":"Mengubah data mentah menjadi dataset yang bersih, tervalidasi, dan siap dianalisis.","prereq":"Python dasar dan matematika level 04.","project":"Pipeline ETL mini untuk membersihkan dataset tabular.","flow":"Pelajari array dan DataFrame, bersihkan masalah data, lakukan EDA/fitur, lalu simpan dalam format yang tepat."},{"level":6,"goal":"Mendesain penyimpanan relasional dan menulis query analitis yang efisien.","prereq":"Data tabular dan konsep key.","project":"Skema transaksi sederhana dengan query ringkasan pelanggan.","flow":"Rancang relasi, kuasai query bertahap, optimalkan indeks/transaksi, lalu kenali warehouse/lake."},{"level":7,"goal":"Memilih algoritma ML sesuai masalah dan memahami cara kerjanya.","prereq":"Level 04–06, terutama statistik dan data preparation.","project":"Eksperimen klasifikasi dan clustering pada dataset kecil.","flow":"Definisikan problem, pahami keluarga algoritma, bandingkan asumsi dan trade-off, lalu pilih baseline."},{"level":8,"goal":"Membangun pipeline ML yang dapat dievaluasi tanpa kebocoran data.","prereq":"Algoritma ML dasar dan dataset bersih.","project":"Pipeline klasifikasi dengan preprocessing dan laporan metrik.","flow":"Pahami estimator, pisahkan data, bangun preprocessing, tuning, ukur metrik, dan analisis kesalahan."},{"level":9,"goal":"Memahami bagaimana neural network belajar dari data.","prereq":"Aljabar linear, kalkulus dasar, dan ML.","project":"Jaringan saraf kecil untuk klasifikasi sederhana.","flow":"Ikuti alur tensor, forward pass, loss, backpropagation, optimisasi, lalu arsitektur jaringan."},{"level":10,"goal":"Melatih, mengevaluasi, menyimpan, dan mereproduksi model dengan framework deep learning.","prereq":"Konsep neural network level 09.","project":"Training loop terukur dan checkpoint model.","flow":"Mulai dari tensor/autograd, dataset dan training loop, akselerasi GPU, ekosistem model dan reproducibility."},{"level":11,"goal":"Menjelaskan tokenisasi, attention, transformer, serta proses pelatihan LLM.","prereq":"Deep learning, probabilitas, dan aljabar linear.","project":"Visualisasi token dan simulasi attention sederhana.","flow":"Dari token dan context window menuju attention, arsitektur, tahapan training, serta keterbatasan model."},{"level":12,"goal":"Mengintegrasikan model melalui API dengan penanganan error, biaya, dan keamanan.","prereq":"Python, HTTP/JSON, dan konsep LLM.","project":"Klien model tiruan dengan streaming simulasi dan retry.","flow":"Pahami endpoint dan autentikasi, format respons, streaming/tool call, reliability, routing, dan secrets."},{"level":13,"goal":"Merancang instruksi dan konteks agar keluaran LLM relevan, terukur, dan aman.","prereq":"Dasar LLM dan integrasi API.","project":"Prompt template dengan versi, contoh, dan test cases.","flow":"Susun instruksi, pilih konteks, kendalikan format, evaluasi prompt, dan pertahankan batas keamanan."},{"level":14,"goal":"Membangun pencarian semantik menggunakan embedding dan vector index.","prereq":"Vektor, similarity, Python, dan database dasar.","project":"Pencarian semantik mini memakai vektor contoh.","flow":"Ubah teks menjadi vektor, ukur kedekatan, pilih index, filter metadata, gabungkan lexical dan semantic search."},{"level":15,"goal":"Membangun RAG yang mengambil sumber relevan dan menghasilkan jawaban berlandaskan bukti.","prereq":"LLM, embeddings, retrieval, dan backend dasar.","project":"Asisten tanya-jawab dokumen dengan kutipan sumber.","flow":"Ingest dokumen, parsing/chunking, indexing, retrieval/reranking, grounding, evaluasi."},{"level":16,"goal":"Membangun agent dan workflow yang memakai tools dengan batas, state, dan pengawasan.","prereq":"LLM API, prompt engineering, dan backend.","project":"Agent terbatas yang memilih satu dari dua tools aman.","flow":"Bedakan workflow dan agent, definisikan tools/state, orkestrasi, human approval, reliability dan security."},{"level":17,"goal":"Menentukan kapan dan bagaimana menyesuaikan model dengan data sendiri.","prereq":"LLM, dataset, evaluasi, dan dasar deep learning.","project":"Rencana eksperimen fine-tuning dengan baseline dan evaluasi.","flow":"Siapkan dataset, pahami SFT dan adapter, atur training, ukur overfitting/safety, bandingkan prompting/RAG."},{"level":18,"goal":"Merancang sistem yang memahami atau menghasilkan teks, gambar, audio, dan video.","prereq":"LLM, model deep learning, evaluasi, dan privasi.","project":"Alur ekstraksi teks dari dokumen gambar dengan validasi manusia.","flow":"Kenali modalitas, encoding, task-specific model, retrieval lintas modalitas, dan evaluasi privasi."},{"level":19,"goal":"Menguji kualitas AI secara sistematis dengan data uji, metrik, dan evaluasi manusia.","prereq":"Dasar ML/LLM dan aplikasi AI yang dapat diuji.","project":"Evaluation harness dengan golden dataset dan regression test.","flow":"Susun dataset evaluasi, pilih metrik, gabungkan judge/manusia, uji RAG/agent, pantau produksi."},{"level":20,"goal":"Menyediakan backend API yang aman dan andal untuk aplikasi AI.","prereq":"Python profesional, HTTP, database, dan LLM API.","project":"REST API sederhana untuk layanan prediksi tiruan.","flow":"Rancang endpoint/schema, async/streaming, cache/queue, auth, rate limit, multi-tenant."},{"level":21,"goal":"Mengoperasikan lifecycle model dan aplikasi AI dari eksperimen hingga deployment.","prereq":"Model ML/LLM, backend, Git, dan Docker dasar.","project":"Pipeline CI/CD konseptual dengan tracking eksperimen dan monitoring.","flow":"Lacak eksperimen dan versi, instrumentasi, container, pipeline rilis, cloud, scaling."},{"level":22,"goal":"Mengoptimalkan inference dan merancang keamanan serta keandalan sistem AI produksi.","prereq":"LLM, backend, deployment, GPU dan observability dasar.","project":"Rancangan serving model dengan target latency, throughput, dan kontrol keamanan.","flow":"Pahami lifecycle inference, optimisasi memori/komputasi, distribusi, reliability, privacy, threat model."},{"level":23,"goal":"Menggabungkan seluruh kompetensi menjadi portofolio AI Engineer yang dapat ditinjau.","prereq":"Materi level 01–22 dan kemampuan membangun aplikasi end-to-end.","project":"Satu aplikasi AI produksi mini lengkap dengan dokumentasi, test, deployment, dan monitoring.","flow":"Pilih masalah, rancang arsitektur, implementasi, evaluasi, rilis, ukur biaya, dokumentasikan dan presentasikan."}];
const snippets=["# Contoh dasar Python\nnilai = [80, 90, 100]\nrata_rata = sum(nilai) / len(nilai)\nprint(f\"Rata-rata: {rata_rata:.1f}\")","# Objek, type hints, dan validasi sederhana\nfrom dataclasses import dataclass\n\n@dataclass\nclass Prediction:\n    label: str\n    score: float\n\ndef is_confident(result: Prediction) -> bool:\n    return result.score >= 0.8\n\nhasil = Prediction(\"positif\", 0.92)\nprint(is_confident(hasil))","# Struktur data dan kompleksitas lookup\nscores = {\"teks\": 0.91, \"gambar\": 0.87}\nquery = \"teks\"\nprint(scores.get(query, 0.0))  # lookup dictionary rata-rata O(1)","# Dot product dan turunan fungsi sederhana\nx = [1.0, 2.0]\nw = [0.5, 0.25]\ndot = sum(a * b for a, b in zip(x, w))\nprint(\"dot =\", dot)\n# Untuk f(x)=x^2, turunan f'(x)=2x\nprint(\"turunan di x=3:\", 2 * 3)","# Bersihkan nilai kosong dan hitung statistik sederhana\nraw = [12, None, 15, 18, None]\nclean = [x for x in raw if x is not None]\nprint(\"data bersih:\", clean)\nprint(\"rata-rata:\", sum(clean) / len(clean))","# Contoh SQL konseptual untuk analitik\nsql = \"\"\"\nSELECT customer_id, SUM(amount) AS total\nFROM orders\nWHERE status = 'paid'\nGROUP BY customer_id\nORDER BY total DESC;\n\"\"\"\nprint(sql)","# Baseline klasifikasi konseptual tanpa library eksternal\nactual = [1, 0, 1, 1]\npredicted = [1, 0, 0, 1]\ncorrect = sum(a == p for a, p in zip(actual, predicted))\nprint(\"akurasi:\", correct / len(actual))","# Pisahkan data sebelum preprocessing untuk mencegah leakage\nX_train = [\"teks A\", \"teks B\", \"teks C\"]\nX_test = [\"teks D\"]\nprint(\"fit preprocessing hanya pada:\", X_train)\nprint(\"transform test tanpa fit ulang:\", X_test)","# Satu neuron: weighted sum + aktivasi ReLU\ninputs = [0.5, 0.2]\nweights = [0.8, -0.1]\nbias = 0.05\nz = sum(x*w for x, w in zip(inputs, weights)) + bias\nrelu = max(0, z)\nprint(relu)","# Bentuk umum training loop PyTorch (perlu install torch)\n# for features, labels in train_loader:\n#     optimizer.zero_grad()\n#     predictions = model(features)\n#     loss = loss_fn(predictions, labels)\n#     loss.backward()\n#     optimizer.step()\nprint(\"Urutan: forward → loss → backward → optimizer step\")","# Ilustrasi self-attention pada satu query dan key\nquery = [1.0, 0.0]\nkeys = [[1.0, 0.0], [0.0, 1.0]]\nscores = [sum(a*b for a,b in zip(query, key)) for key in keys]\nprint(\"skor kemiripan:\", scores)\n# Transformer sebenarnya menambahkan scaling, softmax, value, dan proyeksi.","# Bentuk payload request. Jangan menaruh API key di kode.\npayload = {\n    \"model\": \"model-demo\",\n    \"input\": \"Ringkas dokumen ini\",\n    \"stream\": False\n}\nprint(payload)","# Template prompt dengan pemisahan instruksi dan data\nsystem_instruction = \"Jawab hanya berdasarkan konteks yang diberikan.\"\ncontext = \"Dokumen menyebutkan jadwal pada hari Senin.\"\nquestion = \"Kapan jadwalnya?\"\nprompt = f\"{system_instruction}\\nKonteks: {context}\\nPertanyaan: {question}\"\nprint(prompt)","# Cosine similarity untuk dua vektor contoh\nimport math\n\na = [1.0, 0.0, 1.0]\nb = [1.0, 1.0, 0.0]\ndot = sum(x*y for x,y in zip(a,b))\nnorm_a = math.sqrt(sum(x*x for x in a))\nnorm_b = math.sqrt(sum(y*y for y in b))\nprint(dot / (norm_a * norm_b))","# Alur RAG konseptual: retrieve dahulu, baru generate\nquestion = \"Apa kebijakan pengembalian?\"\nretrieved_chunks = [\"Dokumen A: pengembalian maksimal 7 hari.\"]\ncontext = \"\\n\".join(retrieved_chunks)\nprint(\"Konteks yang diberikan ke model:\", context)\nprint(\"Pertanyaan:\", question)","# Tool registry sederhana dengan allowlist\ndef lookup_order(order_id):\n    return {\"order_id\": order_id, \"status\": \"diproses\"}\n\ntools = {\"lookup_order\": lookup_order}\nrequested_tool = \"lookup_order\"\nif requested_tool in tools:\n    print(tools[requested_tool](\"ORD-001\"))","# Rencana konfigurasi eksperimen fine-tuning (bukan menjalankan training)\nconfig = {\n    \"learning_rate\": 0.0001,\n    \"epochs\": 3,\n    \"adapter\": \"LoRA\",\n    \"evaluation_split\": \"held_out\"\n}\nprint(config)","# Representasi metadata multimodal sederhana\nasset = {\n    \"type\": \"image\",\n    \"source\": \"sample-image.png\",\n    \"consent_checked\": True\n}\nif asset[\"consent_checked\"]:\n    print(\"Aset siap diproses:\", asset[\"type\"])","# Evaluasi jawaban model dengan exact match sederhana\nreferences = [\"Jakarta\", \"Bandung\"]\npredictions = [\"Jakarta\", \"Surabaya\"]\nscore = sum(a == b for a,b in zip(references, predictions)) / len(references)\nprint(\"exact match:\", score)","# Bentuk schema request/response API (contoh data saja)\nrequest = {\"question\": \"Jelaskan RAG\", \"user_id\": \"demo-user\"}\nresponse = {\"answer\": \"RAG mengambil konteks sebelum generasi.\", \"sources\": []}\nprint(response)","# Catatan eksperimen yang bisa disimpan sebagai JSON\nimport json\nrun = {\"model_version\": \"demo-v1\", \"dataset\": \"eval-v1\", \"accuracy\": 0.91}\nprint(json.dumps(run, indent=2))","# Hitung throughput sederhana\ncompleted_requests = 120\nelapsed_seconds = 10\nprint(\"requests/second:\", completed_requests / elapsed_seconds)\n# Pada serving nyata, ukur juga p50/p95 latency dan penggunaan memori.","# Checklist rilis proyek\nchecks = {\n    \"tests_passed\": True,\n    \"secrets_in_environment\": True,\n    \"monitoring_enabled\": True,\n    \"rollback_documented\": False\n}\nfor check, passed in checks.items():\n    print(check, \"OK\" if passed else \"PERLU DITINDAKLANJUTI\")"];
const topicDetails={
"Python syntax":["Aturan penulisan Python: indentasi, titik dua, tanda kurung, string, dan ekspresi harus mengikuti grammar bahasa.","Interpreter membaca struktur ini untuk menentukan blok dan urutan eksekusi.","Seperti tata bahasa; indentasi menandai paragraf atau blok instruksi."],
"variables":["Variabel adalah nama yang merujuk ke sebuah nilai. Assignment mengikat nama ke objek; Python tidak mewajibkan deklarasi tipe di awal.","Dipakai menyimpan input, konfigurasi, fitur, label, skor, dan hasil antara.","Seperti label pada kotak penyimpanan; label dapat diarahkan ke isi yang berbeda."],
"data types":["Tipe data menentukan karakter nilai dan operasi yang sesuai, misalnya int, float, str, bool, list, dict, dan NoneType.","Membantu validasi, perhitungan, serialisasi, dan mencegah operasi yang tidak sesuai.","Seperti memilih wadah: botol untuk cairan, map untuk dokumen."],
"operators":["Operator melakukan operasi aritmetika, perbandingan, logika, keanggotaan, identitas, dan assignment.","Dipakai menghitung fitur, membandingkan threshold, menyusun kondisi, dan memperbarui state.","Seperti tombol kalkulator dan simbol pembanding."],
"input/output":["Input menerima data; output menyajikan hasil. Pada Python dasar, input() menghasilkan string dan print() menampilkan nilai.","Menjadi batas interaksi antara program, pengguna, file, dan proses lain.","Seperti loket: data masuk, hasil keluar."],
"conditionals":["Percabangan if/elif/else memilih blok yang dijalankan berdasarkan nilai truthy atau kondisi boolean.","Dipakai untuk validasi, routing keputusan, threshold prediksi, dan penanganan kasus khusus.","Seperti persimpangan dengan rambu yang menentukan jalur."],
"loops":["Perulangan for mengiterasi item; while mengulang selama kondisi benar. break dan continue mengubah alur loop.","Memproses batch data, dokumen, prediksi, dan percobaan tanpa menulis instruksi berulang.","Seperti memeriksa satu per satu barang dalam daftar."],
"functions":["Fungsi adalah blok bernama yang dapat menerima parameter dan mengembalikan hasil dengan return.","Memecah pipeline menjadi komponen kecil yang dapat dipakai ulang, diuji, dan dirawat.","Seperti mesin: masukkan bahan, proses, keluarkan hasil."],
"collections":["Collection menyimpan beberapa nilai. List berurutan dan mutable, tuple berurutan dan immutable, set menyimpan anggota unik, dictionary memetakan key ke value.","Menyimpan batch fitur, konfigurasi, label, metadata, dan lookup cepat.","Seperti rak, daftar, kantong unik, atau kamus."],
"comprehensions":["Comprehension membangun collection baru dari iterable dengan ekspresi dan filter opsional.","Menyederhanakan transformasi dan penyaringan data dalam satu ekspresi yang terbaca.","Seperti jalur sortir yang langsung mengisi keranjang baru."],
"modules":["Module adalah file Python yang menyediakan namespace; import membuat fungsi, kelas, atau nilai dari modul dapat digunakan.","Memisahkan kode dan memakai pustaka standar maupun package eksternal.","Seperti kotak perkakas khusus yang dapat dipanggil saat dibutuhkan."],
"exceptions":["Exception adalah objek yang menandakan kondisi error saat runtime. try/except menangani jenis error tertentu; finally menjalankan cleanup.","Mencegah input buruk, kegagalan file, atau respons layanan membuat program gagal tanpa penanganan.","Seperti prosedur darurat ketika proses normal terganggu."],
"debugging":["Debugging adalah proses mereproduksi bug, memeriksa state, menemukan akar masalah, lalu menguji perbaikannya.","Menjaga hasil pipeline dan perilaku aplikasi sesuai harapan.","Seperti teknisi menelusuri sumber kerusakan, bukan menebak-nebak."],
"problem solving":["Problem solving menerjemahkan kebutuhan menjadi input, output, batasan, kasus tepi, algoritma, dan pengujian.","Membuat solusi AI dapat dirancang dan diverifikasi sebelum implementasi.","Seperti memecah perjalanan panjang menjadi rute dan titik pemeriksaan."],
"CLI projects.":["CLI adalah antarmuka berbasis teks untuk menjalankan program dengan argumen dan perintah terminal.","Cocok untuk utilitas data, batch inference, skrip otomatisasi, dan tool developer.","Seperti mengoperasikan mesin melalui panel perintah teks."],
"OOP":["Object-oriented programming mengorganisasi perilaku dan data dalam class dan object. Class adalah cetak biru; object adalah instance.","Memodelkan entitas seperti Dataset, Model, Client, dan konfigurasi yang memiliki state serta method.","Seperti cetakan kue dan kue yang dibuat dari cetakan itu."],
"dataclasses":["@dataclass menghasilkan method umum seperti __init__ dan __repr__ untuk class yang terutama menyimpan data.","Membuat konfigurasi dan record data lebih ringkas dengan struktur yang jelas.","Seperti formulir standar yang kolomnya sudah ditentukan."],
"type hints":["Type hints memberi anotasi tipe pada parameter, variabel, dan return. Python tidak otomatis memaksa anotasi saat runtime.","Meningkatkan keterbacaan, dukungan editor, static checking, dan kontrak antar modul.","Seperti label ukuran pada komponen agar mudah dicocokkan."],
"Pydantic":["Pydantic memvalidasi dan mengurai data ke model bertipe berdasarkan deklarasi field.","Memvalidasi payload API, konfigurasi, dan data eksternal sebelum dipakai aplikasi.","Seperti petugas pemeriksa formulir yang memastikan isian sesuai aturan."],
"iterators":["Iterator adalah objek yang menghasilkan item satu per satu melalui __next__; iterable dapat menyediakan iterator.","Memproses data besar secara bertahap tanpa harus memuat semuanya ke memori.","Seperti conveyor belt yang mengeluarkan satu barang setiap kali diminta."],
"generators":["Generator adalah iterator yang dibuat dengan yield; eksekusinya ditangguhkan dan dilanjutkan saat item berikutnya diminta.","Streaming data dan pipeline besar dengan penggunaan memori lebih hemat.","Seperti keran yang mengalirkan data saat dibutuhkan."],
"decorators":["Decorator membungkus fungsi atau class untuk menambah perilaku tanpa mengubah isi inti fungsi.","Logging, autentikasi, caching, retry, dan pengukuran waktu.","Seperti lapisan tambahan pada alat yang menambah fitur."],
"context managers":["Context manager mengelola setup dan cleanup melalui __enter__/__exit__, biasanya dipakai dengan with.","Menutup file, melepas resource, dan mengelola transaksi meskipun terjadi exception.","Seperti meminjam ruang kerja yang otomatis dirapikan saat keluar."],
"async/await":["async mendefinisikan coroutine; await menangguhkan coroutine sampai operasi awaitable siap tanpa memblokir event loop.","Menangani banyak operasi I/O seperti request API atau database secara efisien.","Seperti mengambil nomor antrean sambil mengerjakan hal lain."],
"asyncio":["asyncio adalah library standar untuk concurrent I/O berbasis coroutine dan event loop.","Mengatur banyak request jaringan atau task I/O tanpa membuat thread untuk setiap operasi.","Seperti koordinator yang bergantian memberi waktu pada pekerjaan yang menunggu."],
"concurrency":["Concurrency mengatur beberapa pekerjaan yang progresnya saling berseling; berbeda dari parallelism yang benar-benar berjalan serentak.","Meningkatkan pemanfaatan waktu saat aplikasi menunggu jaringan, disk, atau layanan lain.","Seperti satu koki mengerjakan beberapa pesanan sambil menunggu oven."],
"packaging":["Packaging menyusun kode, metadata, dependency, dan konfigurasi build agar proyek dapat dipasang atau didistribusikan.","Membuat library dan aplikasi konsisten di mesin developer maupun server.","Seperti mengemas produk lengkap dengan label dan petunjuk pemasangan."],
"virtual environments":["Virtual environment mengisolasi interpreter dan dependency Python per proyek.","Mencegah konflik versi package antar proyek.","Seperti ruang kerja terpisah dengan perkakas masing-masing."],
"pytest":["pytest adalah framework testing Python yang menemukan test dan menyediakan assertion serta fixture.","Memverifikasi fungsi, regresi, dan perilaku edge case secara otomatis.","Seperti daftar pemeriksaan kualitas sebelum produk dirilis."],
"logging":["Logging merekam event aplikasi dengan level DEBUG, INFO, WARNING, ERROR, dan CRITICAL.","Membantu diagnosis masalah dan observability tanpa mengandalkan print sementara.","Seperti buku catatan operasional mesin."],
"clean architecture":["Clean architecture memisahkan domain inti dari framework, database, dan detail infrastruktur melalui batas dependensi.","Memudahkan pengujian, perubahan provider model, dan pemeliharaan aplikasi.","Seperti organisasi dengan aturan kerja inti yang tidak bergantung pada merek alat."],
"code quality.":["Kualitas kode mencakup keterbacaan, konsistensi, modularitas, testability, dokumentasi, dan maintainability.","Mengurangi bug dan biaya perubahan saat proyek berkembang.","Seperti merapikan kabel agar mudah diperiksa dan diperbaiki."]
};
const appliedLessons={
"ML problem framing":["ML problem framing adalah proses menerjemahkan kebutuhan menjadi tugas prediksi atau pengelompokan, unit observasi, target, batasan, dan metrik keberhasilan.","Menentukan apakah masalah cocok diselesaikan dengan ML, apa label/fitur yang tersedia, serta bagaimana hasil dipakai pengguna.","Seperti menentukan dulu masalah yang ingin diselesaikan sebelum memilih alat.","problem = {\"task\": \"classification\", \"target\": \"spam\", \"metric\": \"recall\"}\nprint(problem)"],
"supervised/unsupervised learning":["Supervised learning belajar dari contoh yang memiliki target/label; unsupervised learning mencari pola tanpa label target.","Memilih keluarga metode: prediksi label/nilai untuk supervised, atau menemukan struktur/kelompok untuk unsupervised.","Supervised seperti belajar dengan kunci jawaban; unsupervised seperti mengelompokkan benda tanpa diberi nama kelompok.","labeled = [(\"email A\", \"spam\"), (\"email B\", \"ham\")]\nunlabeled = [\"email C\", \"email D\"]\nprint(\"data berlabel:\", labeled)\nprint(\"data tanpa label:\", unlabeled)"],
"linear/logistic regression":["Linear regression memodelkan nilai numerik sebagai kombinasi linear fitur; logistic regression memodelkan probabilitas kelas melalui fungsi sigmoid (umumnya untuk klasifikasi biner).","Baseline untuk prediksi angka (linear) atau probabilitas kelas (logistic); koefisien membantu interpretasi, dengan asumsi dan batasan tertentu.","Linear regression seperti memperpanjang garis tren; logistic regression seperti mengubah skor menjadi peluang 0–1.","import math\nx = 2.0\nlinear_score = 1.5 * x + 0.5\nprobability = 1 / (1 + math.exp(-linear_score))\nprint(\"score:\", linear_score)\nprint(\"probabilitas:\", round(probability, 3))"],
"decision trees":["Decision tree membagi data melalui aturan kondisi bertingkat pada fitur untuk menghasilkan prediksi.","Membangun model yang relatif mudah divisualisasikan; perlu mengendalikan kedalaman agar tidak overfit.","Seperti pohon keputusan: setiap jawaban ya/tidak membawa kita ke cabang berikutnya.","age = 22\nhas_account = True\nif age >= 18 and has_account:\n    prediction = \"eligible\"\nelse:\n    prediction = \"not_eligible\"\nprint(prediction)"],
"random forests":["Random forest menggabungkan banyak decision tree yang dilatih dengan variasi sampel dan fitur, lalu menggabungkan prediksinya.","Mengurangi varians dibanding satu pohon dan menjadi baseline kuat untuk data tabular.","Seperti meminta pendapat banyak pengambil keputusan lalu menggabungkannya.","tree_predictions = [1, 1, 0, 1, 0]\nmajority_vote = max(set(tree_predictions), key=tree_predictions.count)\nprint(\"prediksi mayoritas:\", majority_vote)"],
"SVM":["Support Vector Machine mencari batas pemisah dengan margin maksimum; kernel dapat memodelkan batas non-linear.","Klasifikasi/regresi pada data tertentu; skala fitur dan pemilihan kernel sangat memengaruhi hasil.","Seperti menarik garis pemisah dengan jarak aman terbesar dari kelompok terdekat.","points = [(-2, \"A\"), (-1, \"A\"), (1, \"B\"), (2, \"B\")]\nboundary = 0\nfor x, label in points:\n    predicted = \"A\" if x < boundary else \"B\"\n    print(x, label, predicted)"],
"KNN":["K-Nearest Neighbors memprediksi berdasarkan label atau nilai dari k tetangga terdekat menurut metrik jarak.","Baseline berbasis kemiripan; sensitif terhadap skala fitur, pilihan k, dan biaya pencarian saat data besar.","Seperti menebak jenis buah dari beberapa buah yang paling mirip di dekatnya.","points = [(1, \"A\"), (2, \"A\"), (8, \"B\"), (9, \"B\")]\nquery = 3\nnearest = sorted(points, key=lambda item: abs(item[0] - query))[:3]\nprint(\"tetangga:\", nearest)"],
"Naive Bayes":["Naive Bayes menggunakan Teorema Bayes dengan asumsi independensi bersyarat fitur terhadap kelas.","Klasifikasi probabilistik yang sederhana dan cepat, sering menjadi baseline teks; asumsi independensinya tidak selalu realistis.","Seperti memperbarui dugaan berdasarkan bukti, dengan asumsi tiap petunjuk dihitung secara sederhana.","prior_spam = 0.4\nlikelihood_word_spam = 0.7\nlikelihood_word_ham = 0.2\nscore_spam = prior_spam * likelihood_word_spam\nscore_ham = (1-prior_spam) * likelihood_word_ham\nprint(\"skor relatif:\", score_spam, score_ham)"],
"K-Means":["K-Means mengelompokkan titik ke k cluster dengan memperbarui centroid untuk meminimalkan jumlah kuadrat jarak dalam cluster.","Segmentasi tanpa label; perlu memilih k dan memperhatikan skala serta bentuk cluster.","Seperti membagi peserta ke beberapa kelompok berdasarkan kedekatan karakteristik.","points = [(1, 1), (1.2, 0.9), (8, 8), (8.2, 7.9)]\ncentroids = [(1, 1), (8, 8)]\nprint(\"jumlah titik:\", len(points), \"centroid:\", centroids)"],
"PCA":["Principal Component Analysis memproyeksikan data ke sumbu baru yang menangkap variasi terbesar secara berurutan.","Reduksi dimensi, visualisasi, dan kompresi fitur; komponen perlu ditafsirkan dengan hati-hati.","Seperti merangkum banyak arah pengukuran menjadi beberapa arah utama.","import math\nvectors = [(2, 0), (0, 2), (1, 1)]\nmeans = tuple(sum(p[i] for p in vectors)/len(vectors) for i in range(2))\nprint(\"rata-rata tiap fitur:\", means)\nprint(\"PCA sesungguhnya menghitung eigenvector matriks kovarians.\")"],
"Estimator API":["Estimator API Scikit-learn menyatukan pola fit, predict, dan transform agar komponen model dapat dipakai konsisten.","Memudahkan pipeline, pencarian hyperparameter, dan pertukaran algoritma dengan antarmuka seragam.","Seperti berbagai mesin yang memiliki tombol operasi standar.","class DemoEstimator:\n    def fit(self, X, y):\n        self.label = max(set(y), key=y.count)\n        return self\n    def predict(self, X):\n        return [self.label for _ in X]\n\nmodel = DemoEstimator().fit([[1], [2]], [\"A\", \"A\"])\nprint(model.predict([[3]]))"],
"preprocessing pipelines":["Pipeline menggabungkan transformasi data dan estimator dalam satu alur yang konsisten.","Mencegah transformasi train/test tidak sinkron serta membantu mencegah data leakage ketika fit hanya pada train.","Seperti jalur produksi: setiap barang melewati stasiun yang sama secara berurutan.","steps = [\"impute missing values\", \"scale features\", \"classifier\"]\nfor number, step in enumerate(steps, start=1):\n    print(number, step)"],
"train/validation/test":["Train digunakan mempelajari parameter; validation untuk memilih konfigurasi; test untuk estimasi akhir pada data yang tidak dipakai memilih model.","Mengukur generalisasi dan menghindari optimisme akibat mengevaluasi pada data yang sudah dilihat saat tuning.","Seperti latihan, tryout, lalu ujian akhir yang soalnya belum pernah dilihat.","train = [1, 2, 3, 4, 5, 6]\nvalidation = [7, 8]\ntest = [9, 10]\nprint(len(train), len(validation), len(test))"],
"leakage prevention":["Data leakage terjadi ketika informasi yang tidak tersedia saat prediksi ikut memengaruhi training atau evaluasi.","Menjaga metrik evaluasi realistis; split lebih dulu lalu fit preprocessing hanya pada data train.","Seperti peserta ujian yang diam-diam melihat kunci jawaban sebelum tes.","train = [10, 20, 30]\ntest = [40]\ntrain_mean = sum(train) / len(train)\nprint(\"fit statistic dari train:\", train_mean)\nprint(\"test hanya ditransformasi memakai statistic train\")"],
"precision/recall/F1":["Precision adalah proporsi prediksi positif yang benar; recall adalah proporsi positif aktual yang ditemukan; F1 adalah harmonic mean keduanya.","Memilih metrik klasifikasi sesuai biaya false positive dan false negative; jangan hanya mengandalkan accuracy pada kelas tidak seimbang.","Precision seperti ketepatan alarm; recall seperti kemampuan alarm menemukan semua kejadian.","tp, fp, fn = 8, 2, 1\nprecision = tp / (tp + fp)\nrecall = tp / (tp + fn)\nf1 = 2 * precision * recall / (precision + recall)\nprint(round(precision, 2), round(recall, 2), round(f1, 2))"],
"ROC-AUC":["ROC curve memetakan true positive rate terhadap false positive rate pada berbagai threshold; AUC merangkum kemampuan ranking model.","Membandingkan diskriminasi model lintas threshold; perlu hati-hati pada data sangat tidak seimbang dan kebutuhan operasional tertentu.","Seperti menilai kemampuan alat menyusun kasus berisiko dari paling tinggi ke rendah.","thresholds = [0.9, 0.7, 0.5, 0.3]\nscores = [0.95, 0.82, 0.41, 0.12]\nfor threshold in thresholds:\n    predicted_positive = [s >= threshold for s in scores]\n    print(threshold, predicted_positive)"],
"Perceptrons":["Perceptron menghitung jumlah berbobot dari input ditambah bias, lalu menerapkan fungsi aktivasi untuk menghasilkan output.","Unit dasar jaringan saraf; belajar mengatur bobot agar pemisahan/prediksi semakin sesuai target.","Seperti panel penilai yang memberi bobot berbeda pada tiap petunjuk.","inputs = [0.5, 0.2]\nweights = [0.8, -0.1]\nbias = 0.05\nz = sum(x*w for x, w in zip(inputs, weights)) + bias\nprint(\"weighted sum:\", z, \"ReLU:\", max(0, z))"],
"tensors":["Tensor adalah struktur numerik berdimensi umum: skalar (0D), vektor (1D), matriks (2D), hingga dimensi lebih tinggi.","Mewakili batch, channel, sequence, embedding, dan bobot pada framework deep learning.","Seperti tabel yang bisa memiliki banyak sumbu, bukan hanya baris dan kolom.","tensor_shape = (32, 128, 768)\nprint(\"batch:\", tensor_shape[0])\nprint(\"sequence:\", tensor_shape[1])\nprint(\"hidden size:\", tensor_shape[2])"],
"forward propagation":["Forward propagation meneruskan input melalui layer untuk menghitung prediksi.","Menghasilkan output model yang kemudian dibandingkan dengan target melalui loss function.","Seperti bahan melewati beberapa mesin sampai menjadi produk akhir.","x = 2.0\nweight = 0.5\nbias = 0.1\nprediction = x * weight + bias\nprint(prediction)"],
"backpropagation":["Backpropagation menghitung gradien loss terhadap parameter menggunakan chain rule dari output ke layer sebelumnya.","Memberi informasi arah perubahan bobot agar optimizer dapat memperkecil loss.","Seperti menelusuri kembali proses untuk mengetahui bagian mana yang paling berkontribusi pada kesalahan.","weight = 0.5\nx = 2.0\ntarget = 3.0\nprediction = weight * x\nloss = (prediction - target) ** 2\ngradient = 2 * (prediction - target) * x\nprint(\"loss:\", loss, \"gradient:\", gradient)"],
"loss functions":["Loss function mengukur selisih prediksi model dengan target menurut tujuan optimisasi.","Menjadi sinyal numerik yang diminimalkan selama training; pemilihan loss harus sesuai task dan label.","Seperti skor kesalahan pada latihan yang memberi tahu seberapa jauh dari jawaban benar.","target, prediction = 1.0, 0.7\nsquared_error = (target - prediction) ** 2\nprint(\"MSE satu contoh:\", squared_error)"],
"gradient descent":["Gradient descent memperbarui parameter ke arah negatif gradien dengan learning rate tertentu.","Mengoptimalkan bobot model secara iteratif; learning rate terlalu besar dapat membuat training tidak stabil.","Seperti menuruni bukit dengan langkah yang mengikuti arah turunan paling curam.","weight = 0.0\nlearning_rate = 0.1\nfor step in range(5):\n    gradient = 2 * (weight - 3)\n    weight -= learning_rate * gradient\n    print(step, round(weight, 3))"],
"optimizers":["Optimizer menentukan aturan pembaruan parameter berdasarkan gradien; contoh umum SGD, Adam, dan AdamW.","Mengatur dinamika training, kecepatan konvergensi, dan generalisasi; pilihan optimizer bukan pengganti data/loss yang tepat.","Seperti strategi langkah saat menuruni bukit: langkah tetap atau adaptif.","gradient = 0.8\nlearning_rate = 0.01\nparameter = 1.0\nparameter -= learning_rate * gradient\nprint(parameter)"],
"attention":["Attention menghitung bobot relevansi antar posisi token sehingga representasi dapat menggabungkan informasi dari konteks yang berbeda.","Fondasi Transformer untuk menentukan bagian konteks mana yang berpengaruh pada representasi token saat ini.","Seperti pembaca yang memberi perhatian lebih pada kalimat paling relevan.","query = [1.0, 0.0]\nkeys = [[1.0, 0.0], [0.0, 1.0]]\nscores = [sum(a*b for a,b in zip(query, key)) for key in keys]\nprint(\"attention scores:\", scores)"],
"transformers":["Transformer adalah arsitektur neural network berbasis attention, dengan blok attention dan feed-forward serta mekanisme posisi.","Menjadi arsitektur utama banyak LLM; memahami mask, posisi, dan biaya attention penting untuk memahami batas konteks.","Seperti tim pembaca yang dapat membandingkan bagian teks secara paralel dengan informasi posisi.","tokens = [11, 24, 31]\npositions = list(range(len(tokens)))\nprint(\"token ids:\", tokens)\nprint(\"posisi:\", positions)"],
"PyTorch tensors":["Tensor PyTorch adalah objek numerik yang mendukung operasi tensor dan dapat dilacak autograd.","Menyimpan input, label, parameter, dan hasil komputasi untuk training/inference.","Seperti array yang juga dapat mencatat bagaimana hasil dihitung.","# Contoh PyTorch memerlukan: pip install torch\n# import torch\n# x = torch.tensor([1.0, 2.0])\n# print(x.shape, x.dtype)\nprint(\"Tensor menyimpan data dan metadata seperti shape serta dtype.\")"],
"autograd":["Autograd adalah mekanisme pencatatan operasi dan perhitungan gradien otomatis.","Menghindari perhitungan turunan manual pada model neural network.","Seperti kalkulator yang mencatat langkah perhitungan agar turunan dapat ditelusuri.","# Contoh PyTorch memerlukan torch\n# import torch\n# x = torch.tensor(2.0, requires_grad=True)\n# y = x ** 2\n# y.backward()\n# print(x.grad)  # tensor(4.)\nprint(\"Autograd menghitung gradien secara otomatis.\")"],
"tokens and token IDs":["Token adalah unit teks yang diproses model; token ID adalah bilangan indeks token dalam vocabulary model.","Mengubah teks menjadi urutan angka yang dapat diproses embedding dan transformer; token bukan selalu satu kata utuh.","Seperti memecah kalimat menjadi potongan kode barang lalu memberi nomor pada tiap potongan.","text = \"AI membaca dokumen\"\ntokens = text.lower().split()\nvocabulary = {token: index for index, token in enumerate(sorted(set(tokens)))}\nids = [vocabulary[token] for token in tokens]\nprint(tokens)\nprint(ids)"],
"tokenization":["Tokenization mengubah teks menjadi token sesuai aturan tokenizer model, termasuk subword dan special tokens.","Menentukan panjang input, biaya token, pemotongan konteks, dan cara teks diterjemahkan ke token ID.","Seperti memotong kalimat menjadi kepingan puzzle; ukuran keping tidak selalu sama dengan kata.","text = \"machine learning\"\ntokens = text.split()\nprint(tokens, \"jumlah token demo:\", len(tokens))"],
"context windows":["Context window adalah batas token yang dapat dipertimbangkan model dalam satu input/output sesuai arsitektur dan konfigurasi.","Mengatur panjang dokumen, riwayat chat, prompt, dan strategi pemilihan konteks; batas token bukan jaminan semua konteks dipahami sempurna.","Seperti meja kerja dengan kapasitas terbatas: bahan harus dipilih dan ditata.","context_limit = 8\nprompt_tokens = 6\nreserved_output = 2\nprint(\"sisa input:\", context_limit - prompt_tokens - reserved_output)"],
"self-attention":["Self-attention membentuk query, key, value dari urutan yang sama dan menghitung perhatian antar posisi token.","Membuat representasi token bergantung pada token lain di sequence; mask dapat membatasi informasi yang boleh dilihat.","Seperti setiap kata dalam rapat memperhatikan kata lain untuk memahami konteks kalimat.","query = [1.0, 0.0]\nkeys = [[1.0, 0.0], [0.0, 1.0]]\nvalues = [[10, 0], [0, 20]]\nscores = [sum(a*b for a,b in zip(query,k)) for k in keys]\nprint(\"skor relevansi:\", scores)"],
"GPT and BERT":["GPT umumnya decoder-only dan dilatih untuk prediksi token berikutnya; BERT encoder-only dan dilatih dengan objective masked language modeling.","Memahami perbedaan model generatif autoregresif dan model representasi/encoder untuk task pemahaman.","GPT seperti penulis yang meneruskan kalimat; BERT seperti pembaca yang mengisi bagian kosong dengan melihat konteks dua arah.","tasks = {\"GPT\": \"next-token generation\", \"BERT\": \"masked-token representation\"}\nfor model, objective in tasks.items():\n    print(model, \"→\", objective)"],
"API authentication":["Autentikasi API membuktikan identitas aplikasi/pemanggil, sering melalui bearer token atau mekanisme OAuth/API key.","Mengontrol akses endpoint; kredensial harus disimpan di environment/secret manager, tidak ditulis di source code atau log.","Seperti kartu akses gedung yang diperiksa sebelum masuk.","import os\napi_key = os.getenv(\"DEMO_API_KEY\")\nif api_key:\n    print(\"Kredensial tersedia dari environment\")\nelse:\n    print(\"Atur DEMO_API_KEY di environment; jangan hardcode secret\")"],
"streaming":["Streaming mengirim keluaran bertahap saat tersedia, bukan menunggu seluruh respons selesai.","Mengurangi waktu tunggu awal pada chat dan output panjang; perlu menangani event, partial output, dan koneksi terputus.","Seperti air mengalir dari keran, bukan menunggu ember penuh.","chunks = [\"Halo\", \" \", \"dunia\", \"!\"]\nfor chunk in chunks:\n    print(chunk, end=\"\", flush=True)\nprint()"],
"retries":["Retry mencoba ulang operasi gagal yang bersifat sementara, idealnya dengan batas percobaan dan backoff.","Meningkatkan ketahanan terhadap gangguan jaringan/rate limit; operasi non-idempotent perlu perlindungan agar tidak menggandakan efek.","Seperti mencoba menghubungi kembali ketika sambungan telepon sibuk, tetapi tidak menelepon tanpa henti.","attempts = 3\nfor attempt in range(1, attempts + 1):\n    print(\"percobaan\", attempt)\n    # Sistem nyata memeriksa status error sebelum retry"],
"timeouts":["Timeout membatasi lama menunggu operasi jaringan atau proses eksternal.","Mencegah worker menggantung terlalu lama; pilih timeout sesuai karakter layanan dan sediakan penanganan timeout.","Seperti batas waktu menunggu bus sebelum memilih rencana lain.","timeout_seconds = 5\nsimulated_elapsed = 7\nif simulated_elapsed > timeout_seconds:\n    print(\"Request timeout\")"],
"System/user instructions":["System instruction menetapkan aturan/peran tingkat tinggi; user instruction berisi permintaan pengguna. Prioritas instruksi harus ditangani secara eksplisit.","Mengendalikan perilaku model dan memisahkan aturan aplikasi dari isi permintaan serta data yang tidak tepercaya.","Seperti peraturan kantor dan tugas harian: tugas tidak boleh membatalkan peraturan keselamatan.","system_instruction = \"Jawab hanya berdasarkan sumber yang diberikan.\"\nuser_instruction = \"Ringkas dokumen ini.\"\nprint(system_instruction)\nprint(user_instruction)"],
"few-shot prompting":["Few-shot prompting menyertakan beberapa contoh input-output agar model mengikuti pola tugas.","Mengarahkan format dan gaya respons tanpa melatih ulang bobot model; contoh harus representatif dan tidak saling bertentangan.","Seperti menunjukkan dua contoh pekerjaan sebelum meminta orang mengerjakan soal serupa.","examples = [(\"2+2\", \"4\"), (\"3+5\", \"8\")]\nquestion = \"6+1\"\nprint(\"contoh:\", examples)\nprint(\"soal baru:\", question)"],
"prompt templates":["Prompt template adalah pola instruksi dengan slot yang diisi data saat runtime.","Menjaga prompt konsisten, dapat diuji, dan mudah diberi versi; validasi input slot untuk mengurangi prompt injection.","Seperti formulir surat dengan kolom nama dan tanggal yang diisi otomatis.","template = \"Ringkas dokumen {document_id} dalam {max_points} poin.\"\nprompt = template.format(document_id=\"doc-17\", max_points=3)\nprint(prompt)"],
"embeddings":["Embedding memetakan item seperti teks menjadi vektor numerik sehingga kedekatan semantik dapat dihitung.","Mendukung semantic search, clustering, rekomendasi, dan retrieval; kualitas bergantung model, domain, dan preprocessing.","Seperti menempatkan kalimat pada peta makna: kalimat mirip berada relatif berdekatan.","import math\na, b = [1.0, 0.0], [0.8, 0.2]\ndot = sum(x*y for x,y in zip(a,b))\nnorm_a = math.sqrt(sum(x*x for x in a))\nnorm_b = math.sqrt(sum(y*y for y in b))\nprint(round(dot/(norm_a*norm_b), 3))"],
"vector databases":["Vector database menyimpan embedding dan mendukung pencarian tetangga terdekat, sering dengan metadata filter.","Mencari potongan dokumen/produk yang dekat secara semantik pada koleksi besar; index approximate nearest neighbor punya trade-off recall/latency.","Seperti katalog perpustakaan yang mengurutkan buku berdasarkan kemiripan topik, bukan hanya judul.","records = [{\"id\": \"d1\", \"vector\": [0.9, 0.1]}, {\"id\": \"d2\", \"vector\": [0.1, 0.9]}]\nquery = [1.0, 0.0]\nprint(\"jumlah vektor:\", len(records), \"dimensi:\", len(query))"],
"RAG":["Retrieval-Augmented Generation menggabungkan pencarian sumber eksternal dengan generasi LLM agar jawaban dapat memakai konteks yang diambil.","Mengurangi ketergantungan pada pengetahuan parametris model dan memungkinkan jawaban berbasis dokumen terkini; retrieval dan grounding tetap harus dievaluasi.","Seperti pustakawan mencari buku relevan lalu penulis menyusun jawaban dengan merujuk buku itu.","documents = [{\"id\": \"policy-01\", \"text\": \"Retur maksimal 7 hari.\"}]\nquestion = \"Berapa batas retur?\"\ncontext = [d for d in documents if \"retur\" in d[\"text\"].lower()]\nprint(\"konteks ditemukan:\", context)\nprint(\"pertanyaan:\", question)"],
"chunking":["Chunking membagi dokumen menjadi potongan lebih kecil untuk embedding dan retrieval, sering dengan overlap terkontrol.","Membantu mengambil bagian relevan dan menyesuaikan context window; chunk terlalu kecil kehilangan konteks, terlalu besar mengurangi ketepatan.","Seperti membagi buku menjadi bab dan subbab agar bagian yang dicari mudah ditemukan.","text = \"Kalimat satu. Kalimat dua. Kalimat tiga. Kalimat empat.\"\nsentences = text.split(\". \")\nchunks = [sentences[i:i+2] for i in range(0, len(sentences), 2)]\nprint(chunks)"],
"reranking":["Reranking menilai ulang kandidat retrieval dengan model yang lebih teliti untuk mengurutkan relevansi.","Meningkatkan kualitas top-k konteks sebelum diberikan ke LLM; menambah latency dan biaya.","Seperti pustakawan memilih ulang lima buku terbaik dari daftar hasil pencarian awal.","candidates = [(\"dokumen A\", 0.62), (\"dokumen B\", 0.91), (\"dokumen C\", 0.74)]\nranked = sorted(candidates, key=lambda item: item[1], reverse=True)\nprint(ranked)"],
"grounding":["Grounding mengikat jawaban model pada bukti atau konteks yang tersedia dan meminta model mengakui jika bukti tidak cukup.","Mengurangi klaim tanpa dukungan; cek bahwa setiap pernyataan penting didukung sumber yang benar.","Seperti menjawab ujian dengan menunjukkan halaman buku yang menjadi dasar jawaban.","context = \"Kebijakan: retur maksimal 7 hari.\"\nanswer = \"Batas retur adalah 7 hari.\"\nsource_id = \"policy-01\"\nprint(answer, \"Sumber:\", source_id)"],
"agent":["AI agent adalah sistem yang memilih langkah atau tool berdasarkan tujuan dan observasi, dengan kontrol atas tindakan yang diizinkan.","Mengotomatisasi rangkaian tugas; perlu batas tool, validasi input/output, limit langkah, logging, dan approval untuk tindakan berisiko.","Seperti asisten yang boleh memakai beberapa alat, tetapi hanya sesuai izin dan prosedur.","def lookup_policy(query):\n    return {\"query\": query, \"source\": \"policy-01\"}\n\nallowed_tools = {\"lookup_policy\": lookup_policy}\nprint(allowed_tools[\"lookup_policy\"](\"refund\"))"],
"tool calling":["Tool calling adalah mekanisme model mengusulkan pemanggilan fungsi terstruktur; aplikasi memvalidasi dan mengeksekusi fungsi tersebut.","Menghubungkan model dengan database/API/tool secara terkendali; jangan mengeksekusi nama tool atau argumen tanpa allowlist dan validasi.","Seperti operator mengisi formulir permintaan alat; petugas memeriksa izin sebelum menjalankannya.","def get_weather(city):\n    return {\"city\": city, \"status\": \"demo only\"}\n\ntools = {\"get_weather\": get_weather}\nrequest = {\"name\": \"get_weather\", \"arguments\": {\"city\": \"Jakarta\"}}\nif request[\"name\"] in tools:\n    print(tools[request[\"name\"]](**request[\"arguments\"]))"],
"human approval":["Human approval adalah checkpoint yang meminta persetujuan manusia sebelum tindakan tertentu dilakukan.","Mengendalikan risiko untuk pembayaran, penghapusan, pengiriman pesan, perubahan data, atau tindakan berdampak besar.","Seperti tanda tangan atasan sebelum dokumen resmi dikirim.","action = {\"type\": \"send_email\", \"requires_approval\": True}\napproved = False\nif action[\"requires_approval\"] and not approved:\n    print(\"Tindakan ditahan: menunggu persetujuan\")"],
"fine-tuning":["Fine-tuning melanjutkan training model pretrained pada dataset khusus agar perilaku atau representasinya menyesuaikan domain/task.","Dipilih ketika prompting/RAG belum cukup dan tersedia data berkualitas; memerlukan evaluasi, biaya, dan kontrol risiko.","Seperti memberi pelatihan lanjutan pada orang yang sudah memiliki pengetahuan dasar.","experiment = {\"base_model\": \"demo\", \"method\": \"supervised fine-tuning\", \"epochs\": 2}\nprint(experiment)\nprint(\"Bandingkan dengan baseline prompting dan RAG.\")"],
"LoRA":["Low-Rank Adaptation membekukan bobot dasar dan melatih matriks adapter ber-rank rendah untuk mengurangi parameter yang perlu diperbarui.","Menghemat memori training dan memudahkan adapter khusus; hasil tetap bergantung data, rank, target modules, dan evaluasi.","Seperti memasang modul tambahan pada mesin tanpa mengganti seluruh mesin.","config = {\"method\": \"LoRA\", \"rank\": 8, \"alpha\": 16, \"dropout\": 0.05}\nprint(config)"],
"evaluation harness":["Evaluation harness adalah sistem terulang untuk menjalankan kasus uji, mengumpulkan output, menghitung metrik, dan membandingkan versi model.","Mendeteksi regresi kualitas sebelum rilis dan memantau dampak perubahan prompt/model/data.","Seperti rangkaian tes standar yang dijalankan setiap kali mesin diperbaiki.","cases = [{\"input\": \"2+2\", \"expected\": \"4\"}, {\"input\": \"3+1\", \"expected\": \"4\"}]\npredictions = [\"4\", \"4\"]\npassed = sum(p[\"expected\"] == out for p, out in zip(cases, predictions))\nprint(\"pass rate:\", passed / len(cases))"],
"hallucination":["Hallucination adalah keluaran yang terdengar meyakinkan tetapi tidak didukung fakta atau sumber yang benar.","Mengharuskan verifikasi sumber, abstention saat bukti kurang, dan evaluasi factuality terutama pada sistem RAG.","Seperti seseorang mengisi bagian yang tidak diketahui dengan tebakan yang terdengar yakin.","evidence = \"Tanggal acara: 12 Mei.\"\nclaim = \"Acara berlangsung 12 Mei.\"\nif \"12 Mei\" in evidence:\n    print(\"klaim memiliki dukungan konteks\")"],
"FastAPI":["FastAPI adalah framework Python untuk membangun HTTP API dengan type hints dan validasi request/response.","Menyediakan endpoint inference, retrieval, dan orchestration; produksi perlu auth, timeout, logging, dan pembatasan request.","Seperti loket layanan yang menerima formulir terstruktur dan mengirim hasil terformat.","# Jalankan setelah: pip install fastapi uvicorn\n# from fastapi import FastAPI\n# app = FastAPI()\n# @app.get(\"/health\")\n# def health():\n#     return {\"status\": \"ok\"}\nprint(\"Contoh endpoint health ditulis sebagai komentar; butuh FastAPI.\")"],
"Docker":["Docker mengemas aplikasi dan dependency ke image agar lingkungan eksekusi lebih konsisten.","Membantu menjalankan service AI dengan konfigurasi yang dapat direproduksi; image tetap perlu dipindai dan secrets tidak boleh dibake ke image.","Seperti mengemas aplikasi beserta perlengkapan yang dibutuhkan dalam satu kontainer.","dockerfile = [\"FROM python:3.12-slim\", \"WORKDIR /app\", \"COPY requirements.txt .\", \"RUN pip install -r requirements.txt\"]\nprint(\"\\n\".join(dockerfile))"],
"monitoring":["Monitoring mengumpulkan metrik/log/traces untuk mengetahui kesehatan layanan, performa model, dan perubahan distribusi data.","Mendeteksi latency, error rate, biaya, drift, serta penurunan kualitas setelah deployment.","Seperti panel indikator kendaraan yang memperingatkan masalah sebelum kendaraan berhenti.","metrics = {\"latency_ms\": 180, \"error_rate\": 0.01, \"requests\": 250}\nfor name, value in metrics.items():\n    print(name, value)"],
"latency":["Latency adalah waktu yang diperlukan dari request dimulai hingga respons diterima; p50/p95/p99 menggambarkan persentil distribusi.","Mengukur pengalaman pengguna dan menemukan bottleneck; rata-rata saja dapat menyembunyikan request lambat.","Seperti waktu antrean: yang penting bukan hanya rata-rata, tetapi juga pengalaman orang yang menunggu paling lama.","latencies_ms = [80, 90, 100, 120, 400]\nprint(\"min:\", min(latencies_ms), \"max:\", max(latencies_ms))\nprint(\"median:\", sorted(latencies_ms)[len(latencies_ms)//2])"]
};
function describe(topic,idx){const a=appliedLessons[topic];if(a)return a[0];const d=topicDetails[topic];if(d)return d[0];const g=guides[idx];const known=definitions[topic]||definitions[topic.toLowerCase()];if(known)return known+" Dalam level ini, pelajari definisi formalnya, asumsi yang digunakan, kapan tepat dipakai, dan keterbatasannya.";return topic+" adalah konsep pada "+phases[idx].title+". Pelajari komponen utamanya, asumsi yang mendasari, cara kerjanya, dan kondisi ketika pendekatan ini tepat atau tidak tepat digunakan."}
function role(topic,idx){const a=appliedLessons[topic];if(a)return a[1];const d=topicDetails[topic];if(d)return d[1];const g=guides[idx];return "Dalam proyek level ini, "+topic+" membantu mencapai tujuan: "+g.goal+" Pahami input, output, dependency, dan trade-off sebelum memilihnya untuk sistem produksi."}
function analogy(topic,idx){const a=appliedLessons[topic];if(a)return a[2];const d=topicDetails[topic];if(d)return d[2];const analogies=["Seperti komponen dalam resep: setiap langkah punya bahan masuk dan hasil yang bisa diperiksa.","Seperti alat khusus di bengkel; pilih alat berdasarkan pekerjaan dan batas kemampuannya.","Seperti jalur pengiriman; struktur dan urutan menentukan kecepatan serta ketepatan.","Seperti peta dan pengukuran; model matematis membantu memperkirakan hasil.","Seperti dapur data; bahan mentah dibersihkan dan disiapkan sebelum diolah.","Seperti perpustakaan teratur; relasi dan indeks membantu menemukan informasi.","Seperti strategi belajar dari contoh; tiap algoritma punya asumsi dan kelemahan.","Seperti ujian yang adil; data evaluasi harus terpisah dari data latihan.","Seperti jaringan neuron; sinyal diteruskan dan bobot disesuaikan dari kesalahan.","Seperti ruang latihan; framework mengatur data, komputasi, dan pembaruan bobot.","Seperti mesin prediksi teks yang membaca token dalam konteks.","Seperti layanan loket; request dikirim dengan format dan aturan akses.","Seperti menulis brief yang jelas untuk rekan kerja.","Seperti mencari buku berdasarkan makna, bukan hanya kata persis.","Seperti pustakawan yang mencari sumber sebelum menjawab.","Seperti operator yang memakai alat dengan izin dan batas yang jelas.","Seperti melatih ulang keterampilan dengan contoh yang dipilih.","Seperti menggabungkan mata dan telinga untuk memahami situasi.","Seperti rubrik penilaian yang menguji kualitas dari banyak sisi.","Seperti pintu layanan yang mengatur request masuk dan respons keluar.","Seperti jalur produksi dengan pencatatan versi dan pemantauan.","Seperti mengatur lalu lintas dan keselamatan pabrik saat beban tinggi.","Seperti pameran karya dengan bukti proses, hasil, dan evaluasi."];return analogies[idx]}
